// src/effects/postfx/camera-frame-settings.ts
var GROUPS = [
  "rendering",
  "ssao",
  "bloom",
  "grading",
  "colorLUT",
  "vignette",
  "taa",
  "fringing",
  "colorEnhance",
  "dof",
  "volumetricFog"
];
function copyValue(value) {
  if (Array.isArray(value)) return value.slice();
  if (value && typeof value.clone === "function" && !("device" in value)) {
    return value.clone();
  }
  return value;
}
function snapshotFrameSettings(frame) {
  const groups = {};
  const source = frame;
  for (const group of GROUPS) {
    const settings = source[group];
    if (!settings || typeof settings !== "object") continue;
    const copy = {};
    for (const key2 of Object.keys(settings)) copy[key2] = copyValue(settings[key2]);
    groups[group] = copy;
  }
  return { groups, debug: frame.debug };
}
function restoreFrameSettings(frame, settings) {
  const target = frame;
  for (const group of GROUPS) {
    const saved = settings.groups[group];
    const live = target[group];
    if (!saved || !live || typeof live !== "object") continue;
    for (const key2 of Object.keys(saved)) live[key2] = copyValue(saved[key2]);
  }
  frame.debug = settings.debug;
}

// src/effects/postfx/postfx.ts
var PostFX = class {
  _scene;
  /** Current pass set - mutated by add/remove. Drives the NEXT rebuild's
   *  install order. */
  _passes = [];
  /** Snapshot of what the LAST rebuild actually installed. Driven by
   *  `_rebuild`, used by the next `_rebuild` to know what to uninstall.
   *
   *  Critical: this is intentionally distinct from `_passes`. `remove(p)`
   *  splices `p` out of `_passes` BEFORE calling `_rebuild`, so iterating
   *  `_passes` to tear down would skip the removed pass and leak its
   *  resources. Iterating `_installed` instead reliably uninstalls
   *  everything that was last alive. */
  _installed = [];
  _frameConfig = {};
  _intermediates = [];
  _rebuilding = false;
  _resizeHandler;
  constructor(scene) {
    this._scene = scene;
    this._resizeHandler = () => {
      if (this._scene.cameraFrame === null && this._passes.length === 0) return;
      this._rebuild();
    };
  }
  /** Add a pass. Returns the same instance for chaining / handle capture. */
  add(pass) {
    if (pass.configureFrame) {
      pass.configureFrame(this._scene, this._frameConfig);
    }
    this._passes.push(pass);
    this._ensureResizeHook();
    this._rebuild();
    return pass;
  }
  /** Remove a previously-added pass. Triggers a chain rebuild. */
  remove(pass) {
    const i = this._passes.indexOf(pass);
    if (i < 0) return;
    this._passes.splice(i, 1);
    this._rebuild();
  }
  /** Internal - called by `Scene.destroy`. */
  destroyAll() {
    this._scene.graphicsDevice.off("resizecanvas", this._resizeHandler);
    this._uninstallAll();
    this._freeIntermediates();
    this._passes.length = 0;
  }
  // ── internals ────────────────────────────────────────────────────────
  _hookedResize = false;
  _ensureResizeHook() {
    if (this._hookedResize) return;
    this._scene.graphicsDevice.on("resizecanvas", this._resizeHandler);
    this._hookedResize = true;
  }
  _restoreLook(frame, look) {
    if (!look) return;
    restoreFrameSettings(frame, look);
    frame.update();
  }
  _needsFrame() {
    return this._frameConfig.sceneDepthMap === true || this._frameConfig.requireFrame === true;
  }
  _capturingPasses() {
    return this._passes.filter((p) => p.capturesScene === true);
  }
  _uninstallAll() {
    if (this._installed.length === 0) return;
    for (let i = this._installed.length - 1; i >= 0; i--) {
      try {
        this._installed[i].uninstall(this._scene);
      } catch (err) {
        console.warn("[PostFX] uninstall threw", err);
      }
    }
    this._installed = [];
  }
  _freeIntermediates() {
    for (const rt of this._intermediates) {
      const tex = rt.colorBuffer;
      try {
        rt.destroy();
      } catch {
      }
      try {
        tex?.destroy();
      } catch {
      }
    }
    this._intermediates = [];
  }
  _allocateIntermediate(name) {
    const device = this._scene.graphicsDevice;
    const tex = new Texture(device, {
      name: `${name}-color`,
      width: Math.max(1, device.width),
      height: Math.max(1, device.height),
      format: PIXELFORMAT_RGBA8,
      mipmaps: false,
      minFilter: FILTER_LINEAR,
      magFilter: FILTER_LINEAR,
      addressU: ADDRESS_CLAMP_TO_EDGE,
      addressV: ADDRESS_CLAMP_TO_EDGE
    });
    const rt = new RenderTargetCtor({
      name,
      colorBuffer: tex,
      depth: false,
      stencil: false,
      samples: 1
    });
    this._intermediates.push(rt);
    return rt;
  }
  /**
   * Tear down and re-install the full chain. Idempotent - safe to call as
   * often as you like. Guarded against re-entry (a pass's uninstall that
   * triggers a resize, for example).
   */
  _rebuild() {
    if (this._rebuilding) return;
    this._rebuilding = true;
    try {
      this._uninstallAll();
      const cam = this._scene.cameraEntity.camera;
      const hadFrame = this._scene.cameraFrame !== null;
      const look = this._scene.cameraFrame ? snapshotFrameSettings(this._scene.cameraFrame) : null;
      if (this._scene.cameraFrame) {
        this._scene.cameraFrame.destroy();
        this._scene.cameraFrame = null;
      }
      if (cam) cam.renderTarget = null;
      this._freeIntermediates();
      if (this._passes.length === 0) {
        if (hadFrame) this._restoreLook(this._scene.getOrCreateCameraFrame(), look);
        return;
      }
      const capturing = this._capturingPasses();
      const outputTargets = capturing.map(() => null);
      if (capturing.length > 0) {
        const firstSceneRT = capturing[0].getSceneCaptureRT?.() ?? null;
        if (cam && firstSceneRT) {
          cam.renderTarget = firstSceneRT;
        }
        for (let i = 0; i < capturing.length - 1; i++) {
          outputTargets[i] = this._allocateIntermediate(`postfx-chain-${i}`);
        }
        outputTargets[capturing.length - 1] = null;
      }
      const frame = this._needsFrame() || hadFrame ? this._scene.getOrCreateCameraFrame() : null;
      if (frame) this._restoreLook(frame, look);
      let captureIdx = 0;
      for (const pass of this._passes) {
        const ctx = pass.capturesScene ? {
          frame,
          // First capturing pass reads its own sceneCaptureRT internally.
          // Later passes read the PRIOR pass's output (an intermediate).
          inputTarget: captureIdx === 0 ? null : outputTargets[captureIdx - 1],
          outputTarget: outputTargets[captureIdx]
        } : { frame, inputTarget: null, outputTarget: null };
        try {
          pass.install(this._scene, ctx);
          this._installed.push(pass);
        } catch (err) {
          console.error("[PostFX] install threw", err);
        }
        if (pass.capturesScene) captureIdx++;
      }
    } finally {
      this._rebuilding = false;
    }
  }
};

// src/effects/postfx/base-capturing-pass.ts
import {
  ADDRESS_CLAMP_TO_EDGE as ADDRESS_CLAMP_TO_EDGE2,
  Color,
  Entity,
  EVENT_PRERENDER_LAYER,
  FILTER_LINEAR as FILTER_LINEAR2,
  Layer,
  PIXELFORMAT_RGBA8 as PIXELFORMAT_RGBA82,
  QuadRender,
  RenderTarget,
  SEMANTIC_POSITION,
  ShaderUtils,
  Texture as Texture2
} from "playcanvas";
var BaseCapturingPass = class {
  capturesScene = true;
  /** Options passed at construction. Available to subclasses if they
   *  need to read `shaderName` etc. */
  options;
  /** Captured in `configureFrame`. Stays set across uninstall/install
   *  cycles per rule 4. */
  _scene = null;
  // ── Owned scene-capture RT (used when we're the first capturing pass) ──
  _ownSceneRT = null;
  _ownSceneTex = null;
  _ownSceneW = 0;
  _ownSceneH = 0;
  // ── Per-install ephemeral state ──
  _input = null;
  _output = null;
  _frame = null;
  _composeLayer = null;
  _composeLayerId = -1;
  _composeCameraEntity = null;
  _quad = null;
  _handler = null;
  constructor(options) {
    this.options = options;
  }
  // ── Subclass extension points ─────────────────────────────────────────
  /**
   * Bind any custom uniforms your shader uses. `uSourceTex` has already
   * been bound to the input RT's color texture by the time this runs.
   * Default is a no-op - override if your shader needs more uniforms.
   */
  bindUniforms(_scope, _device, _ctx) {
  }
  /**
   * Return the scene-capture RT size in pixels. Default is backbuffer.
   * Override to capture at a different resolution.
   */
  getSceneCaptureRTSize(device) {
    return { w: device.width, h: device.height };
  }
  // ── PostFXPass lifecycle ───────────────────────────────────────────────
  configureFrame(scene, rendering) {
    this._scene = scene;
    if (this.options.needsSceneDepth) {
      rendering.sceneDepthMap = true;
    } else {
      rendering.requireFrame = true;
    }
  }
  getSceneCaptureRT() {
    this._ensureOwnSceneRT();
    return this._ownSceneRT;
  }
  install(scene, ctx) {
    this._scene = scene;
    this._output = ctx.outputTarget;
    this._frame = ctx.frame;
    if (ctx.inputTarget) {
      this._input = ctx.inputTarget;
    } else {
      this._ensureOwnSceneRT();
      this._input = this._ownSceneRT;
    }
    if (!this._input) {
      throw new Error(`[${this.options.shaderName}] install: no input RT could be resolved`);
    }
    const device = scene.graphicsDevice;
    const mainCam = scene.cameraEntity.camera;
    if (!mainCam) {
      throw new Error(`[${this.options.shaderName}] install: scene.cameraEntity has no camera`);
    }
    this._composeLayer = new Layer({
      name: `${this.options.shaderName}-layer`,
      clearColorBuffer: false,
      clearDepthBuffer: false,
      passThrough: false
    });
    scene.app.scene.layers.push(this._composeLayer);
    this._composeLayerId = this._composeLayer.id;
    const priorityOffset = this.options.composePriorityOffset ?? 3;
    this._composeCameraEntity = new Entity(`${this.options.shaderName}-camera`);
    scene.app.root.addChild(this._composeCameraEntity);
    this._composeCameraEntity.addComponent("camera", {
      clearColor: new Color(0, 0, 0, 1),
      clearColorBuffer: true,
      clearDepthBuffer: false,
      clearStencilBuffer: false,
      renderTarget: this._output,
      layers: [this._composeLayerId],
      priority: (mainCam.priority ?? 0) + priorityOffset
    });
    this._composeCameraEntity.camera.renderTarget = this._output;
    const shader = ShaderUtils.createShader(device, {
      uniqueName: this.options.shaderName,
      attributes: { vertex_position: SEMANTIC_POSITION },
      vertexChunk: "fullscreenQuadVS",
      fragmentGLSL: this.options.fragmentGLSL,
      fragmentWGSL: this.options.fragmentWGSL
    });
    this._quad = new QuadRender(shader);
    const ctxSnapshot = {
      frame: this._frame,
      inputTarget: this._input,
      outputTarget: this._output
    };
    this._handler = (_cam, layer, transparent) => {
      if (layer?.id !== this._composeLayerId || transparent) return;
      if (!this._input || !this._quad) return;
      const sourceTex = this._input.colorBuffer;
      if (!sourceTex) return;
      device.scope.resolve("uSourceTex").setValue(sourceTex);
      this.bindUniforms(device.scope, device, ctxSnapshot);
      this._quad.render();
    };
    scene.app.scene.on(EVENT_PRERENDER_LAYER, this._handler);
  }
  uninstall(_scene) {
    if (!this._composeCameraEntity && !this._composeLayer) return;
    if (this._scene && this._handler) {
      try {
        this._scene.app.scene.off(EVENT_PRERENDER_LAYER, this._handler);
      } catch {
      }
    }
    this._handler = null;
    if (this._composeCameraEntity) {
      this._composeCameraEntity.parent?.removeChild(this._composeCameraEntity);
      try {
        this._composeCameraEntity.destroy();
      } catch {
      }
      this._composeCameraEntity = null;
    }
    if (this._composeLayer && this._scene) {
      this._scene.app.scene.layers.remove(this._composeLayer);
    }
    this._composeLayer = null;
    this._composeLayerId = -1;
    this._quad = null;
    this._input = null;
    this._output = null;
    this._frame = null;
    if (this._ownSceneRT) {
      try {
        this._ownSceneRT.destroy();
      } catch {
      }
      this._ownSceneRT = null;
    }
    if (this._ownSceneTex) {
      try {
        this._ownSceneTex.destroy();
      } catch {
      }
      this._ownSceneTex = null;
    }
    this._ownSceneW = 0;
    this._ownSceneH = 0;
  }
  // ── internals ────────────────────────────────────────────────────────
  /** Idempotent: allocates our own scene-capture RT at the requested size,
   *  reuses if size unchanged. */
  _ensureOwnSceneRT() {
    if (!this._scene) return;
    const device = this._scene.graphicsDevice;
    const { w, h } = this.getSceneCaptureRTSize(device);
    const wi = Math.max(1, Math.floor(w));
    const hi = Math.max(1, Math.floor(h));
    if (this._ownSceneRT && this._ownSceneW === wi && this._ownSceneH === hi) return;
    if (this._ownSceneRT) {
      try {
        this._ownSceneRT.destroy();
      } catch {
      }
    }
    if (this._ownSceneTex) {
      try {
        this._ownSceneTex.destroy();
      } catch {
      }
    }
    this._ownSceneTex = new Texture2(device, {
      name: `${this.options.shaderName}-scene-color`,
      width: wi,
      height: hi,
      format: PIXELFORMAT_RGBA82,
      mipmaps: false,
      minFilter: FILTER_LINEAR2,
      magFilter: FILTER_LINEAR2,
      addressU: ADDRESS_CLAMP_TO_EDGE2,
      addressV: ADDRESS_CLAMP_TO_EDGE2
    });
    this._ownSceneRT = new RenderTarget({
      name: `${this.options.shaderName}-scene-rt`,
      colorBuffer: this._ownSceneTex,
      depth: false,
      stencil: false,
      samples: 1
    });
    this._ownSceneW = wi;
    this._ownSceneH = hi;
  }
};

