import { Vec3 as Vec322 } from "playcanvas";
async function prewarmJsonVfxPrefabs(stage, dataFile, resolveUrl) {
  const tmp = [];
  const origin = new Vec322(0, 0, 0);
  for (const [, data] of Object.entries(dataFile)) {
    try {
      const prefab = resolveUrl ? new JsonVfxPrefab(data, stage.registry, resolveUrl, stage.layerId) : stage.buildPrefab(data);
      const instance2 = prefab.create(stage.app, stage.contentRoot);
      instance2.spawn(origin);
      tmp.push({ instance: instance2 });
    } catch (err) {
      console.warn("[VFX prewarm] failed to build prefab; skipping:", err);
    }
  }
  await new Promise((r) => requestAnimationFrame(() => r()));
  await new Promise((r) => requestAnimationFrame(() => r()));
  for (const { instance: instance2 } of tmp) {
    instance2.reset();
    instance2.dispose();
  }
}

