    const device = this._scene.graphicsDevice;
    const mesh = this._mesh ?? new Mesh5(device);
    mesh.setPositions(pos, 3, pos.length / 3);
    mesh.setColors(col, 4, col.length / 4);
    mesh.setUvs(0, uv, 2, uv.length / 2);
    mesh.setIndices(idx2);
